        ?><section class="requirement-summary card"><div><span class="eyebrow">DEPLOYMENT REQUIREMENT #<?=$a['id']?></span><h2><?=e($a['title'])?></h2><p><?=e($location['name'])?> · <?=e(dt($a['starts_at']))?> – <?=e(dt($a['ends_at']))?></p><p><?=nl2br(e($a['instructions']))?></p><p><strong>Required competency:</strong> <?=e($a['required_skill']?:'No specific requirement')?></p></div><div class="staffing-count"><strong><?=$assigned?><span>/<?=$a['required_nurses']?></span></strong><small>NURSES ASSIGNED</small></div></section>
        <section class="card"><div class="section-heading"><div><h2>Potential deployment candidates</h2><p>Eligibility includes the full requested interval. The authorized supervisor makes the final decision.</p></div></div><div class="table-wrap"><table><thead><tr><th>Nurse / home assignment</th><th>Competencies</th><th>Eligibility & conflicts</th><th>Action</th></tr></thead><tbody><?php foreach($service->candidates((int)$a['id']) as $c): ?><tr><td><div class="person"><?=avatar($c['name'])?><div><strong><?=e($c['name'])?></strong><small><?=e($c['location_name']?:'No home location')?></small></div></div></td><td><?=e($c['specialization'])?><small><?=e($c['skills'])?></small></td><td><?=badge($c['eligible']?'Available':'Unavailable')?><?php foreach($c['reasons'] as $reason): ?><small><?=e($reason)?></small><?php endforeach ?></td><td><?php if($c['eligible'] && $assigned<$a['required_nurses']): ?><details class="deploy-confirm"><summary class="button small primary">Review & deploy</summary><div class="confirm-body"><h3>Confirm official deployment</h3><p><strong><?=e($c['name'])?></strong><br><?=e($a['title'])?><br><?=e($location['name'])?><br><?=e(dt($a['starts_at']))?> – <?=e(dt($a['ends_at']))?></p><p><?=e($service->record('deployment_reasons',(int)$a['reason_id'])['name'])?></p><p><?=nl2br(e($a['instructions']))?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="deploy"><input type="hidden" name="activity_id" value="<?=$a['id']?>"><input type="hidden" name="nurse_id" value="<?=$c['id']?>"><input type="hidden" name="return" value="?page=deployment&activity=<?=$a['id']?>"><button class="primary">Confirm deployment</button></form></div></details><?php else: ?><span class="muted"><?=$assigned>=$a['required_nurses']?'Fully staffed':'Not eligible'?></span><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section><?php
    }
